package com.redraft.pdfcore.selection

import com.redraft.pdfcore.PdfRect

/**
 * Character boxes dumped from a REAL PDF by PDFium itself (FPDFText_GetCharBox, same engine
 * as the app).  The page is Letter, 21 text lines, Times 9 pt, 10.5 pt leading, left margin 72.
 * Include PDFium's own CR/LF line-break characters, exactly as the text page returns them.
 *
 * Box = left, bottom, right, top in absolute PDF user space (y up).
 */
internal data class RealChar(
    val index: Int,
    val text: String,
    val left: Float,
    val bottom: Float,
    val right: Float,
    val top: Float,
    val fontSize: Float,
)

internal fun realPdfiumChars(): List<CharBox> = REAL_CHARS.map {
    CharBox(
        index = it.index,
        text = it.text,
        rect = PdfRect(minOf(it.left, it.right), minOf(it.bottom, it.top), maxOf(it.left, it.right), maxOf(it.bottom, it.top)),
        fontSizePt = it.fontSize,
    )
}

